#sports-events-page .no-tickets-fallback p { font-size: 36px; font-weight: 800; color: var(--secondary-color); margin-bottom: 20px; }
#sports-events-page .ant-divider { margin: 30px 0px; }
@media screen and (max-width: 1024px) {
  #sports-events-page { padding: 15px; }
  #sports-events-page .search-wrapper { margin-bottom: 20px; }
  #sports-events-page .event-gallery-wrapper { margin: 15px 0px; }
  #sports-events-page .ticket-options-wrapper { margin: 20px 0px; }
  #sports-events-page .no-tickets-fallback { min-height: 250px; padding: 50px 20px; margin: 30px 0px; }
  #sports-events-page .no-tickets-fallback p { font-size: 22px; }
  #sports-events-page .ant-divider { margin: 20px 0px; }
}
@media screen and (max-width: 768px) {
  #sports-events-page { padding: 10px; }
  #sports-events-page .search-wrapper { margin-bottom: 15px; }
  #sports-events-page .event-gallery-wrapper { margin: 10px 0px; }
  #sports-events-page .ticket-options-wrapper { margin: 15px 0px; }
  #sports-events-page .no-tickets-fallback { min-height: 200px; padding: 40px 15px; margin: 20px 0px; }
  #sports-events-page .no-tickets-fallback p { font-size: 20px; }
  #sports-events-page .ant-divider { margin: 15px 0px; }
}
.bot-fab { position: fixed; bottom: 20px; right: 20px; z-index: 999; width: 56px; height: 56px; border-radius: 50%; background: var(--primary, #1677ff); color: rgb(255, 255, 255); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; box-shadow: rgba(0, 0, 0, 0.18) 0px 8px 40px; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: transform 0.2s, background 0.2s; }
.bot-fab:hover { transform: scale(1.08); }
.bot-fab--open { background: rgb(89, 89, 89); }
.bot-fab__badge { position: absolute; top: 10px; right: 10px; width: 10px; height: 10px; border-radius: 50%; background: rgb(82, 196, 26); border: 2px solid rgb(255, 255, 255); }
.direction-rtl .bot-fab { right: auto; left: 20px; }
.bot-panel { position: fixed; bottom: 84px; right: 20px; z-index: 999; width: 380px; height: 600px; background: rgb(255, 255, 255); border-radius: 16px; box-shadow: rgba(0, 0, 0, 0.18) 0px 8px 40px; display: flex; flex-direction: column; overflow: hidden; animation: 0.25s ease 0s 1 normal none running botSlideUp; }
@media (max-width: 480px) {
  .bot-panel { width: 100vw; height: 80vh; bottom: 0px; right: 0px; border-radius: 16px 16px 0px 0px; }
}
.bot-panel__body { flex: 1 1 0%; display: flex; flex-direction: column; overflow: hidden; }
.direction-rtl .bot-panel { right: auto; left: 20px; }
@media (max-width: 480px) {
  .direction-rtl .bot-panel { left: 0px; }
}
@keyframes botSlideUp { 
  0% { opacity: 0; transform: translateY(20px); }
  100% { opacity: 1; transform: translateY(0px); }
}
