.b2c-step-completion-overlay { position: absolute; inset: 0px; z-index: 10; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, rgba(67, 220, 129, 0.97), rgba(43, 181, 100, 0.97)); color: rgb(255, 255, 255); border-radius: inherit; opacity: 0; pointer-events: none; transition: opacity 420ms cubic-bezier(0.22, 1, 0.36, 1); backdrop-filter: blur(2px); }
